window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-eeae4c0dfe722a81"]={"versions": [{"id": "FIG-eeae4c0dfe722a81", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm (AUTOSAR M2/M3-Metamodell-Ausschnitt, <em>Manifest Specification</em>).\n</li><li><strong>Technischer Zweck:</strong> Modellierung der Bereitstellung und Kommunikationsanbindung von <strong>SOVD</strong> (<em>Service-Oriented Vehicle Diagnostics</em>, ASAM SOVD) in der AUTOSAR Adaptive Platform (Release R22-11).\n</li><li><strong>Architektonische Einordnung:</strong>\n<ul class=\"fig-list\"><li>Spezialisierung von <code>NonOsModuleInstantiation</code> zur softwareseitigen Instanziierung von SOVD-Funktionsbausteinen auf einer <em>Adaptive Machine</em>.\n</li><li>Differenzierung zwischen internen Diagnose-Servern (<code>SovdServerInstantiation</code>) und fahrzeugzentralen/externen Diagnose-Gateways (<code>SovdGatewayInstantiation</code>).\n</li><li>Abbildung der Netzwerk- und Transportschicht-Parametrierung (Ethernet, TCP/UDP-Endpoints, TLS-Absicherung) über AUTOSAR-Standardelemente (<code>CommunicationConnector</code>, <code>SecureComProps</code>).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metamodell-Klassen &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>SovdModuleInstantiation</code></strong> <em>(abstract, spezialisiert <code>NonOsModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Basisklasse aller SOVD-Instanzen im Manifest.\n</li><li>Attribut: <code>nodeIdentifier: String [0..1]</code> – Eindeutiger logischer Bezeichner des SOVD-Knotens im Fahrzeugnetzwerk.\n</li></ul>\n</li><li><strong><code>SovdServerInstantiation</code></strong> <em>(konkret, spezialisiert <code>SovdModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Repräsentiert einen lokalen SOVD-Server, der Diagnoseressourcen einer bestimmten Fahrzeugkomponente bereitstellt.\n</li><li>Attribut: <code>componentQualifier: String [0..1]</code> – Bezeichner der diagnostizierten logischen/physischen Komponente gemäß SOVD-Spezifikation.\n</li></ul>\n</li><li><strong><code>SovdGatewayInstantiation</code></strong> <em>(konkret, spezialisiert <code>SovdModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Repräsentiert das SOVD-Gateway, das externe REST-/WebSocket-Anfragen bündelt, terminiert und an interne Server/Subsysteme vermittelt.\n</li></ul>\n</li><li><strong><code>SovdGatewayEthernetCredentials</code></strong> <em>(abstract)</em>:\n<ul class=\"fig-list\"><li>Basisstruktur für Netzwerkadressierungsdaten des Gateways.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>ipv4Address: Ip4AddressString [0..1]</code>\n</li><li><code>ipv6Address: Ip6AddressString [0..1]</code>\n</li><li><code>udpPort: PositiveInteger [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><strong><code>SovdGatewayLocalEndpointTcpConfig</code></strong> <em>(konkret, spezialisiert <code>SovdGatewayEthernetCredentials</code>)</em>:\n<ul class=\"fig-list\"><li>Konfiguriert die lokalen TCP-Endpunkte des SOVD-Gateways.\n</li><li>Attribut: <code>tcpPort: PositiveInteger [0..1]</code>\n</li></ul>\n</li><li><strong><code>SecureComProps</code></strong> <em>(abstract, Basisklasse: <code>ARElement</code>)</em> / <strong><code>TlsSecureComProps</code></strong> <em>(konkret)</em>:\n<ul class=\"fig-list\"><li>Sicherheitskonfiguration für verschlüsselte Kommunikationsverbindungen (TLS/DTLS).\n</li></ul>\n</li><li><strong><code>CommunicationConnector</code></strong> <em>(abstract, Basisklasse: <code>Identifiable</code>)</em>:\n<ul class=\"fig-list\"><li>Physischer/logischer Netzanbindungspunkt.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>createEcuWakeupSource: Boolean [0..1]</code>\n</li><li><code>pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code>\n</li></ul>\n</li></ul>\n</li><li><strong><code>EthernetCommunicationConnector</code></strong> <em>(konkret, spezialisiert <code>CommunicationConnector</code>)</em>:\n<ul class=\"fig-list\"><li>Spezifische Ethernet-Netzwerkankopplung.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>maximumTransmissionUnit: PositiveInteger [0..1]</code>\n</li><li><code>neighborCacheSize: PositiveInteger [0..1]</code>\n</li><li><code>pathMtuEnabled: Boolean [0..1]</code>\n</li><li><code>pathMtuTimeout: TimeValue [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><strong><code>NetworkEndpoint</code></strong> <em>(konkret, Basisklasse: <code>Identifiable</code>)</em>:\n<ul class=\"fig-list\"><li>Spezifiziert IP-Ebene und Host-Konfiguration.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>fullyQualifiedDomainName: String [0..1]</code>\n</li><li><code>priority: PositiveInteger [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><strong><code>ApApplicationEndpoint</code></strong> <em>(konkret, Basisklasse: <code>Identifiable</code>)</em>:\n<ul class=\"fig-list\"><li>Spezifischer Anwendungs-Endpunkt auf Socket-Ebene.\n</li><li>Attribut: <code>priority: PositiveInteger [0..1]</code>\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen, Aggregationen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>SovdModuleInstantiation</code> → <code>CommunicationConnector</code></strong>:\n<ul class=\"fig-list\"><li>Rolle <code>+communicationConnector</code>, Kardinalität <code>0..*</code> (navigierbare Assoziation). Verknüpft die SOVD-Instanz mit den zugrundeliegenden Kommunikationskanälen.\n</li></ul>\n</li><li><strong><code>SovdModuleInstantiation</code> → <code>SecureComProps</code></strong>:\n<ul class=\"fig-list\"><li>Rolle <code>+securePropsForTcp</code>, Kardinalität <code>0..1</code> (Sicherheitsprofil für TCP-Payload).\n</li><li>Rolle <code>+securePropsForUdp</code>, Kardinalität <code>0..1</code> (Sicherheitsprofil für UDP-Discovery / Lightweight Messaging).\n</li></ul>\n</li><li><strong><code>SovdGatewayInstantiation</code> → <code>SecureComProps</code></strong>:\n<ul class=\"fig-list\"><li>Rolle <code>+securePropsForExternalComm</code>, Kardinalität <code>0..1</code> (Dediziertes TLS-Profil für die fahrzeugexterne Diagnoseschnittstelle).\n</li></ul>\n</li><li><strong><code>SovdGatewayInstantiation</code> ▶ <code>SovdGatewayLocalEndpointTcpConfig</code></strong>:\n<ul class=\"fig-list\"><li>Rolle <code>+unicastCredentials</code>, Kardinalität <code>0..1</code> (Komposition/Besitzbeziehung). Definiert die konkreten lokalen IP- und Port-Bindungen des Gateways.\n</li></ul>\n</li><li><strong><code>EthernetCommunicationConnector</code> → <code>NetworkEndpoint</code></strong>:\n<ul class=\"fig-list\"><li>Rolle <code>+unicastNetworkEndpoint</code>, Kardinalität <code>0..*</code> (Assoziation zu IP-Netzwerk-Endpunkten).\n</li></ul>\n</li><li><strong><code>EthernetCommunicationConnector</code> ▶ <code>ApApplicationEndpoint</code></strong>:\n<ul class=\"fig-list\"><li>Rolle <code>+apApplicationEndpoint</code>, Kardinalität <code>0..*</code> (Komposition von AUTOSAR-Adaptive-Applikations-Sockets).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein rein deklaratives Metamodell-Diagramm handelt, sind keine Laufzeit-Zustandsübergänge abgebildet. Für die Systemintegration bestimmt das Modell folgende Initialisierungs- und Kommunikationsabläufe:</p>\n<pre class=\"fig-pre\"><code>[Externer SOVD-Client]\n       |\n       | 1. TCP Connect (IP/Port via SovdGatewayLocalEndpointTcpConfig)\n       v\n[SovdGatewayInstantiation]\n       |\n       | 2. TLS Handshake (Validierung via securePropsForExternalComm / TlsSecureComProps)\n       v\n[Authentifizierter Session-Kanal]\n       |\n       | 3. Routing anhand URI / nodeIdentifier / componentQualifier\n       +--------------------------------------------+\n       |                                            |\n       v (interne TCP/UDP-Kommunikation)            v\n[SovdServerInstantiation A]               [SovdServerInstantiation B]\n(abgesichert via securePropsForTcp/Udp)  (abgesichert via securePropsForTcp/Udp)</code></pre>\n<ol class=\"fig-list\"><li><strong>Stack-Bootstrapping:</strong> Der Adaptive-Core wertet das Manifest aus, instanziiert den SOVD-Gateway-Daemon und bindet diesen an die via <code>+unicastCredentials</code> konfigurierte IP-Adresse und den <code>tcpPort</code>.\n</li><li><strong>TLS-Terminierung am Gateway:</strong> Eingehende Client-Verbindungen werden über die in <code>+securePropsForExternalComm</code> referenzierten Zertifikate/Cipher-Suites (<code>TlsSecureComProps</code>) authentifiziert und entschlüsselt.\n</li><li><strong>Dispatching:</strong> Das Gateway löst eingehende REST-/JSON-Anfragen über den Pfad auf:\n<ul class=\"fig-list\"><li>Zuordnung zur passenden <code>SovdServerInstantiation</code> via <code>nodeIdentifier</code> bzw. <code>componentQualifier</code>.\n</li><li>Weiterleitung über die internen Endpunkte (<code>EthernetCommunicationConnector</code>), optional getrennt abgesichert über <code>securePropsForTcp</code>/<code>securePropsForUdp</code>.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Konfiguration (TPS_MANI_01400, TPS_MANI_01401):</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen bei der Manifest-Erstellung entscheiden, ob ein Prozess als vollwertiges Gateway (<code>SovdGatewayInstantiation</code>) oder als reiner interner Server (<code>SovdServerInstantiation</code>) fungiert.\n</li><li>Wenn <code>SovdGatewayInstantiation</code> verwendet wird, ist <code>unicastCredentials</code> zwingend für die statische Bereitstellung von IP/Port zu modellieren, falls kein dynamischer Service-Discovery-Mechanismus greift.\n</li></ul>\n</li><li><strong>Security &amp; Krypto-Stack-Integration:</strong>\n<ul class=\"fig-list\"><li>Verlinkung auf <code>TlsSecureComProps</code> bedingt die Bereitstellung entsprechender Crypto-Treiber und Schlüssel im <em>Crypto Service Manager</em> (CSM / Key Storage Providers).\n</li><li>Externe und interne Verbindungen können unterschiedliche Sicherheitsstufen besitzen (<code>securePropsForExternalComm</code> vs. <code>securePropsForTcp/Udp</code>).\n</li></ul>\n</li><li><strong>Netzwerk-Stack-Bindung:</strong>\n<ul class=\"fig-list\"><li><code>EthernetCommunicationConnector</code> erfordert zwingend konsistente MTU- (<code>maximumTransmissionUnit</code>) und Path-MTU-Konfigurationen (<code>pathMtuEnabled</code>, <code>pathMtuTimeout</code>), um IP-Fragmentierung bei großen diagnostischen JSON-/REST-Payloads zu verhindern.\n</li><li>Die Zuordnung zu <code>ApApplicationEndpoint</code> bestimmt die Port-Mappings auf POSIX-Socket-Ebene für den generierten Applikations-Code.\n</li></ul>\n</li></ul>"}, {"id": "FIG-555910f9c3304252", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm (AUTOSAR M2/M3-Metamodell-Ausschnitt, <em>Manifest Specification</em>).\n</li><li><strong>Technischer Zweck:</strong> Modellierung der Bereitstellung und Kommunikationsanbindung von <strong>SOVD</strong> (<em>Service-Oriented Vehicle Diagnostics</em>, ASAM SOVD) in der AUTOSAR Adaptive Platform (Release R22-11).\n</li><li><strong>Architektonische Einordnung:</strong>\n<ul class=\"fig-list\"><li>Spezialisierung von <code>NonOsModuleInstantiation</code> zur softwareseitigen Instanziierung von SOVD-Funktionsbausteinen auf einer <em>Adaptive Machine</em>.\n</li><li>Differenzierung zwischen internen Diagnose-Servern (<code>SovdServerInstantiation</code>) und fahrzeugzentralen/externen Diagnose-Gateways (<code>SovdGatewayInstantiation</code>).\n</li><li>Abbildung der Netzwerk- und Transportschicht-Parametrierung (Ethernet, TCP/UDP-Endpoints, TLS-Absicherung) über AUTOSAR-Standardelemente (<code>CommunicationConnector</code>, <code>SecureComProps</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metamodell-Klassen &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>SovdModuleInstantiation</code></strong> <em>(abstract, spezialisiert <code>NonOsModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Basisklasse aller SOVD-Instanzen im Manifest.\n</li><li>Attribut: <code>nodeIdentifier: String [0..1]</code> – Eindeutiger logischer Bezeichner des SOVD-Knotens im Fahrzeugnetzwerk.\n</li></ul>\n</li><li><strong><code>SovdServerInstantiation</code></strong> <em>(konkret, spezialisiert <code>SovdModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Repräsentiert einen lokalen SOVD-Server, der Diagnoseressourcen einer bestimmten Fahrzeugkomponente bereitstellt.\n</li><li>Attribut: <code>componentQualifier: String [0..1]</code> – Bezeichner der diagnostizierten logischen/physischen Komponente gemäß SOVD-Spezifikation.\n</li></ul>\n</li><li><strong><code>SovdGatewayInstantiation</code></strong> <em>(konkret, spezialisiert <code>SovdModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Repräsentiert das SOVD-Gateway, das externe REST-/WebSocket-Anfragen bündelt, terminiert und an interne Server/Subsysteme vermittelt.\n</li></ul>\n</li><li><strong><code>SovdGatewayEthernetCredentials</code></strong> <em>(abstract)</em>:\n<ul class=\"fig-list\"><li>Basisstruktur für Netzwerkadressierungsdaten des Gateways.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>ipv4Address: Ip4AddressString [0..1]</code>\n</li><li><code>ipv6Address: Ip6AddressString [0..1]</code>\n</li><li><code>udpPort: PositiveInteger [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><strong><code>SovdGatewayLocalEndpointTcpConfig</code></strong> <em>(konkret, spezialisiert <code>SovdGatewayEthernetCredentials</code>)</em>:\n<ul class=\"fig-list\"><li>Konfiguriert die lokalen TCP-Endpunkte des SOVD-Gateways.\n</li><li>Attribut: <code>tcpPort: PositiveInteger [0..1]</code>\n</li></ul>\n</li><li><strong><code>SecureComProps</code></strong> <em>(abstract, Basisklassen: <code>ARElement</code>, <code>UploadableDesignElement</code>)</em> / <strong><code>TlsSecureComProps</code></strong> <em>(konkret)</em>:\n<ul class=\"fig-list\"><li>Sicherheitskonfiguration für verschlüsselte Kommunikationsverbindungen (TLS/DTLS). Qualifiziert als <code>UploadableDesignElement</code> für das Design- und Update-Management.\n</li></ul>\n</li><li><strong><code>CommunicationConnector</code></strong> <em>(abstract, Basisklasse: <code>Identifiable</code>)</em>:\n<ul class=\"fig-list\"><li>Physischer/logischer Netzanbindungspunkt.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>createEcuWakeupSource: Boolean [0..1]</code>\n</li><li><code>pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code>\n</li></ul>\n</li></ul>\n</li><li><strong><code>EthernetCommunicationConnector</code></strong> <em>(konkret, spezialisiert <code>CommunicationConnector</code>)</em>:\n<ul class=\"fig-list\"><li>Spezifische Ethernet-Netzwerkankopplung.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>maximumTransmissionUnit: PositiveInteger [0..1]</code>\n</li><li><code>neighborCacheSize: PositiveInteger [0..1]</code>\n</li><li><code>pathMtuEnabled: Boolean [0..1]</code>\n</li><li><code>pathMtuTimeout: TimeValue [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><strong><code>NetworkEndpoint</code></strong> <em>(konkret, Basisklasse: <code>Identifiable</code>)</em>:\n<ul class=\"fig-list\"><li>Spezifiziert IP-Ebene und Host-Konfiguration.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>fullyQualifiedDomainName: String [0..1]</code>\n</li><li><code>priority: PositiveInteger [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><strong><code>ApApplicationEndpoint</code></strong> <em>(konkret, Basisklasse: <code>Identifiable</code>)</em>:\n<ul class=\"fig-list\"><li>Spezifischer Anwendungs-Endpunkt auf Socket-Ebene.\n</li><li>Attribut: <code>priority: PositiveInteger [0..1]</code>\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen, Aggregationen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>SovdModuleInstantiation</code> → <code>CommunicationConnector</code>:</strong>\n<ul class=\"fig-list\"><li>Assoziation <code>+communicationConnector</code> (<code>0..*</code>): Weist der SOVD-Modulinstanz Netzwerk-Konnektoren der Machine zu.\n</li></ul>\n</li><li><strong><code>SovdModuleInstantiation</code> → <code>SecureComProps</code>:</strong>\n<ul class=\"fig-list\"><li>Assoziation <code>+securePropsForTcp</code> (<code>0..1</code>): Sicherheitskonfiguration für interne TCP-Verbindungen.\n</li><li>Assoziation <code>+securePropsForUdp</code> (<code>0..1</code>): Sicherheitskonfiguration für interne UDP-Verbindungen.\n</li></ul>\n</li><li><strong><code>SovdGatewayInstantiation</code> → <code>SecureComProps</code>:</strong>\n<ul class=\"fig-list\"><li>Assoziation <code>+securePropsForExternalComm</code> (<code>0..1</code>): TLS-Sicherheitskonfiguration (<code>TlsSecureComProps</code>) für externe SOVD-Kommunikationskanäle.\n</li></ul>\n</li><li><strong><code>SovdGatewayInstantiation</code> → <code>SovdGatewayLocalEndpointTcpConfig</code>:</strong>\n<ul class=\"fig-list\"><li>Komposition <code>+unicastCredentials</code> (<code>0..1</code>): Besitzt lokale TCP-Verbindungs- und Adressierungsdaten des Gateways.\n</li></ul>\n</li><li><strong><code>EthernetCommunicationConnector</code> → <code>NetworkEndpoint</code>:</strong>\n<ul class=\"fig-list\"><li>Assoziation <code>+unicastNetworkEndpoint</code> (<code>0..*</code>): Referenziert IP-Endpunkte des Netzwerkinterfaces.\n</li></ul>\n</li><li><strong><code>EthernetCommunicationConnector</code> → <code>ApApplicationEndpoint</code>:</strong>\n<ul class=\"fig-list\"><li>Komposition <code>+apApplicationEndpoint</code> (<code>0..*</code>): Aggregiert Socket-Endpunkte für Anwendungen.\n</li></ul>\n</li><li><strong>Generalisierungs-Hierarchien:</strong>\n<ul class=\"fig-list\"><li><code>SovdServerInstantiation</code> → <code>SovdModuleInstantiation</code> → <code>NonOsModuleInstantiation</code>\n</li><li><code>SovdGatewayInstantiation</code> → <code>SovdModuleInstantiation</code> → <code>NonOsModuleInstantiation</code>\n</li><li><code>SovdGatewayLocalEndpointTcpConfig</code> → <code>SovdGatewayEthernetCredentials</code>\n</li><li><code>EthernetCommunicationConnector</code> → <code>CommunicationConnector</code> → <code>Identifiable</code>\n</li><li><code>TlsSecureComProps</code> → <code>SecureComProps</code> → <code>ARElement</code>, <code>UploadableDesignElement</code>\n</li><li><code>NetworkEndpoint</code> → <code>Identifiable</code>\n</li><li><code>ApApplicationEndpoint</code> → <code>Identifiable</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein rein deklaratives Metamodell-Diagramm handelt, sind keine Laufzeit-Zustandsübergänge abgebildet. Für die Systemintegration bestimmt das Modell folgende Initialisierungs- und Kommunikationsabläufe:</p>\n<pre class=\"fig-pre\"><code>[Externer SOVD-Client]\n       |\n       | 1. TCP Connect (IP/Port via SovdGatewayLocalEndpointTcpConfig)\n       v\n[SovdGatewayInstantiation]\n       |\n       | 2. TLS Handshake (Validierung via securePropsForExternalComm / TlsSecureComProps)\n       v\n[Authentifizierter Session-Kanal]\n       |\n       | 3. Routing anhand URI / nodeIdentifier / componentQualifier\n       +--------------------------------------------+\n       |                                            |\n       v (interne TCP/UDP-Kommunikation)            v\n[SovdServerInstantiation A]               [SovdServerInstantiation B]\n(abgesichert via securePropsForTcp/Udp)  (abgesichert via securePropsForTcp/Udp)</code></pre>\n<ol class=\"fig-list\"><li><strong>Stack-Bootstrapping:</strong> Der Adaptive-Core wertet das Manifest aus, instanziiert den SOVD-Gateway-Daemon und bindet diesen an die via <code>+unicastCredentials</code> konfigurierte IP-Adresse und den <code>tcpPort</code>.\n</li><li><strong>TLS-Terminierung am Gateway:</strong> Eingehende Client-Verbindungen werden über die in <code>+securePropsForExternalComm</code> referenzierten Zertifikate/Cipher-Suites (<code>TlsSecureComProps</code>) authentifiziert und entschlüsselt.\n</li><li><strong>Dispatching:</strong> Das Gateway löst eingehende REST-/JSON-Anfragen über den Pfad auf:\n<ul class=\"fig-list\"><li>Zuordnung zur passenden <code>SovdServerInstantiation</code> via <code>nodeIdentifier</code> bzw. <code>componentQualifier</code>.\n</li><li>Weiterleitung über die internen Endpunkte (<code>EthernetCommunicationConnector</code>), optional getrennt abgesichert über <code>securePropsForTcp</code>/<code>securePropsForUdp</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Konfiguration (TPS_MANI_01400, TPS_MANI_01401):</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen bei der Manifest-Erstellung entscheiden, ob ein Prozess als vollwertiges Gateway (<code>SovdGatewayInstantiation</code>) oder als reiner interner Server (<code>SovdServerInstantiation</code>) fungiert.\n</li><li>Wenn <code>SovdGatewayInstantiation</code> verwendet wird, ist <code>unicastCredentials</code> zwingend für die statische Bereitstellung von IP/Port zu modellieren, falls kein dynamischer Service-Discovery-Mechanismus greift.\n</li></ul>\n</li><li><strong>Security &amp; Krypto-Stack-Integration:</strong>\n<ul class=\"fig-list\"><li>Verlinkung auf <code>TlsSecureComProps</code> bedingt die Bereitstellung entsprechender Crypto-Treiber und Schlüssel im <em>Crypto Service Manager</em> (CSM / Key Storage Providers).\n</li><li>Externe und interne Verbindungen können unterschiedliche Sicherheitsstufen besitzen (<code>securePropsForExternalComm</code> vs. <code>securePropsForTcp/Udp</code>).\n</li></ul>\n</li><li><strong>Netzwerk-Stack-Bindung:</strong>\n<ul class=\"fig-list\"><li><code>EthernetCommunicationConnector</code> erfordert zwingend konsistente MTU- (<code>maximumTransmissionUnit</code>) und Path-MTU-Konfigurationen (<code>pathMtuEnabled</code>, <code>pathMtuTimeout</code>), um IP-Fragmentierung bei großen diagnostischen JSON-/REST-Payloads zu verhindern.\n</li><li>Die Zuordnung zu <code>ApApplicationEndpoint</code> bestimmt die Port-Mappings auf POSIX-Socket-Ebene für den generierten Applikations-Code.\n</li></ul>\n</li></ul>"}, {"id": "FIG-95dd614989bc744b", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm (AUTOSAR M2/M3-Metamodell-Ausschnitt, <em>Manifest Specification</em>).\n</li><li><strong>Technischer Zweck:</strong> Modellierung der Bereitstellung und Kommunikationsanbindung von <strong>SOVD</strong> (<em>Service-Oriented Vehicle Diagnostics</em>, ASAM SOVD) in der AUTOSAR Adaptive Platform (Release R22-11).\n</li><li><strong>Architektonische Einordnung:</strong>\n<ul class=\"fig-list\"><li>Spezialisierung von <code>NonOsModuleInstantiation</code> zur softwareseitigen Instanziierung von SOVD-Funktionsbausteinen auf einer <em>Adaptive Machine</em>.\n</li><li>Differenzierung zwischen internen Diagnose-Servern (<code>SovdServerInstantiation</code>) und fahrzeugzentralen/externen Diagnose-Gateways (<code>SovdGatewayInstantiation</code>).\n</li><li>Abbildung der Netzwerk- und Transportschicht-Parametrierung (Ethernet, TCP/UDP-Endpoints, TLS-Absicherung) über AUTOSAR-Standardelemente (<code>CommunicationConnector</code>, <code>SecureComProps</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metamodell-Klassen &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>SovdModuleInstantiation</code></strong> <em>(abstract, spezialisiert <code>NonOsModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Basisklasse aller SOVD-Instanzen im Manifest.\n</li><li>Attribut: <code>nodeIdentifier: String [0..1]</code> – Eindeutiger logischer Bezeichner des SOVD-Knotens im Fahrzeugnetzwerk.\n</li></ul>\n</li><li><strong><code>SovdServerInstantiation</code></strong> <em>(konkret, spezialisiert <code>SovdModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Repräsentiert einen lokalen SOVD-Server, der Diagnoseressourcen einer bestimmten Fahrzeugkomponente bereitstellt.\n</li><li>Attribut: <code>componentQualifier: String [0..1]</code> – Bezeichner der diagnostizierten logischen/physischen Komponente gemäß SOVD-Spezifikation.\n</li></ul>\n</li><li><strong><code>SovdGatewayInstantiation</code></strong> <em>(konkret, spezialisiert <code>SovdModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Repräsentiert das SOVD-Gateway, das externe REST-/WebSocket-Anfragen bündelt, terminiert und an interne Server/Subsysteme vermittelt.\n</li></ul>\n</li><li><strong><code>SovdGatewayEthernetCredentials</code></strong> <em>(abstract)</em>:\n<ul class=\"fig-list\"><li>Basisstruktur für Netzwerkadressierungsdaten des Gateways.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>ipv4Address: Ip4AddressString [0..1]</code>\n</li><li><code>ipv6Address: Ip6AddressString [0..1]</code>\n</li><li><code>udpPort: PositiveInteger [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><strong><code>SovdGatewayLocalEndpointTcpConfig</code></strong> <em>(konkret, spezialisiert <code>SovdGatewayEthernetCredentials</code>)</em>:\n<ul class=\"fig-list\"><li>Konfiguriert die lokalen TCP-Endpunkte des SOVD-Gateways.\n</li><li>Attribut: <code>tcpPort: PositiveInteger [0..1]</code>\n</li></ul>\n</li><li><strong><code>SecureComProps</code></strong> <em>(abstract, Basisklassen: <code>ARElement</code>, <code>UploadableDesignElement</code>)</em> / <strong><code>TlsSecureComProps</code></strong> <em>(konkret)</em>:\n<ul class=\"fig-list\"><li>Sicherheitskonfiguration für verschlüsselte Kommunikationsverbindungen (TLS/DTLS). Qualifiziert als <code>UploadableDesignElement</code> für das Design- und Update-Management.\n</li></ul>\n</li><li><strong><code>CommunicationConnector</code></strong> <em>(abstract, Basisklasse: <code>Identifiable</code>)</em>:\n<ul class=\"fig-list\"><li>Physischer/logischer Netzanbindungspunkt.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>createEcuWakeupSource: Boolean [0..1]</code>\n</li><li><code>pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code>\n</li></ul>\n</li></ul>\n</li><li><strong><code>EthernetCommunicationConnector</code></strong> <em>(konkret, spezialisiert <code>CommunicationConnector</code>)</em>:\n<ul class=\"fig-list\"><li>Spezifische Ethernet-Netzwerkankopplung.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>maximumTransmissionUnit: PositiveInteger [0..1]</code>\n</li><li><code>neighborCacheSize: PositiveInteger [0..1]</code>\n</li><li><code>pathMtuEnabled: Boolean [0..1]</code>\n</li><li><code>pathMtuTimeout: TimeValue [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><strong><code>NetworkEndpoint</code></strong> <em>(konkret, Basisklasse: <code>Identifiable</code>)</em>:\n<ul class=\"fig-list\"><li>Spezifiziert IP-Ebene und Host-Konfiguration.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>fullyQualifiedDomainName: String [0..1]</code>\n</li><li><code>priority: PositiveInteger [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><strong><code>ApApplicationEndpoint</code></strong> <em>(konkret, Basisklasse: <code>Identifiable</code>)</em>:\n<ul class=\"fig-list\"><li>Spezifischer Anwendungs-Endpunkt auf Socket-Ebene.\n</li><li>Attribut: <code>priority: PositiveInteger [0..1]</code>\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen, Aggregationen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>SovdModuleInstantiation</code> → <code>CommunicationConnector</code>:</strong>\n<ul class=\"fig-list\"><li>Assoziation <code>+communicationConnector</code> (<code>0..*</code>): Weist der SOVD-Modulinstanz Netzwerk-Konnektoren der Machine zu.\n</li></ul>\n</li><li><strong><code>SovdModuleInstantiation</code> → <code>SecureComProps</code>:</strong>\n<ul class=\"fig-list\"><li>Assoziation <code>+securePropsForTcp</code> (<code>0..1</code>): Sicherheitskonfiguration für interne TCP-Verbindungen.\n</li><li>Assoziation <code>+securePropsForUdp</code> (<code>0..1</code>): Sicherheitskonfiguration für interne UDP-Verbindungen.\n</li></ul>\n</li><li><strong><code>SovdGatewayInstantiation</code> → <code>SecureComProps</code>:</strong>\n<ul class=\"fig-list\"><li>Assoziation <code>+securePropsForExternalComm</code> (<code>0..1</code>): TLS-Sicherheitskonfiguration (<code>TlsSecureComProps</code>) für externe SOVD-Kommunikationskanäle.\n</li></ul>\n</li><li><strong><code>SovdGatewayInstantiation</code> → <code>SovdGatewayLocalEndpointTcpConfig</code>:</strong>\n<ul class=\"fig-list\"><li>Komposition <code>+unicastCredentials</code> (<code>0..1</code>): Besitzt lokale TCP-Verbindungs- und Adressierungsdaten des Gateways.\n</li></ul>\n</li><li><strong><code>EthernetCommunicationConnector</code> → <code>NetworkEndpoint</code>:</strong>\n<ul class=\"fig-list\"><li>Assoziation <code>+unicastNetworkEndpoint</code> (<code>0..*</code>): Referenziert IP-Endpunkte des Netzwerkinterfaces.\n</li></ul>\n</li><li><strong><code>EthernetCommunicationConnector</code> → <code>ApApplicationEndpoint</code>:</strong>\n<ul class=\"fig-list\"><li>Komposition <code>+apApplicationEndpoint</code> (<code>0..*</code>): Aggregiert Socket-Endpunkte für Anwendungen.\n</li></ul>\n</li><li><strong>Generalisierungs-Hierarchien:</strong>\n<ul class=\"fig-list\"><li><code>SovdServerInstantiation</code> → <code>SovdModuleInstantiation</code> → <code>NonOsModuleInstantiation</code>\n</li><li><code>SovdGatewayInstantiation</code> → <code>SovdModuleInstantiation</code> → <code>NonOsModuleInstantiation</code>\n</li><li><code>SovdGatewayLocalEndpointTcpConfig</code> → <code>SovdGatewayEthernetCredentials</code>\n</li><li><code>EthernetCommunicationConnector</code> → <code>CommunicationConnector</code> → <code>Identifiable</code>\n</li><li><code>TlsSecureComProps</code> → <code>SecureComProps</code> → <code>ARElement</code>, <code>UploadableDesignElement</code>\n</li><li><code>NetworkEndpoint</code> → <code>Identifiable</code>\n</li><li><code>ApApplicationEndpoint</code> → <code>Identifiable</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein rein deklaratives Metamodell-Diagramm handelt, sind keine Laufzeit-Zustandsübergänge abgebildet. Für die Systemintegration bestimmt das Modell folgende Initialisierungs- und Kommunikationsabläufe:</p>\n<pre class=\"fig-pre\"><code>[Externer SOVD-Client]\n       |\n       | 1. TCP Connect (IP/Port via SovdGatewayLocalEndpointTcpConfig)\n       v\n[SovdGatewayInstantiation]\n       |\n       | 2. TLS Handshake (Validierung via securePropsForExternalComm / TlsSecureComProps)\n       v\n[Authentifizierter Session-Kanal]\n       |\n       | 3. Routing anhand URI / nodeIdentifier / componentQualifier\n       +--------------------------------------------+\n       |                                            |\n       v (interne TCP/UDP-Kommunikation)            v\n[SovdServerInstantiation A]               [SovdServerInstantiation B]\n(abgesichert via securePropsForTcp/Udp)  (abgesichert via securePropsForTcp/Udp)</code></pre>\n<ol class=\"fig-list\"><li><strong>Stack-Bootstrapping:</strong> Der Adaptive-Core wertet das Manifest aus, instanziiert den SOVD-Gateway-Daemon und bindet diesen an die via <code>+unicastCredentials</code> konfigurierte IP-Adresse und den <code>tcpPort</code>.\n</li><li><strong>TLS-Terminierung am Gateway:</strong> Eingehende Client-Verbindungen werden über die in <code>+securePropsForExternalComm</code> referenzierten Zertifikate/Cipher-Suites (<code>TlsSecureComProps</code>) authentifiziert und entschlüsselt.\n</li><li><strong>Dispatching:</strong> Das Gateway löst eingehende REST-/JSON-Anfragen über den Pfad auf:\n<ul class=\"fig-list\"><li>Zuordnung zur passenden <code>SovdServerInstantiation</code> via <code>nodeIdentifier</code> bzw. <code>componentQualifier</code>.\n</li><li>Weiterleitung über die internen Endpunkte (<code>EthernetCommunicationConnector</code>), optional getrennt abgesichert über <code>securePropsForTcp</code>/<code>securePropsForUdp</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Konfiguration (TPS_MANI_01400, TPS_MANI_01401):</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen bei der Manifest-Erstellung entscheiden, ob ein Prozess als vollwertiges Gateway (<code>SovdGatewayInstantiation</code>) oder als reiner interner Server (<code>SovdServerInstantiation</code>) fungiert.\n</li><li>Wenn <code>SovdGatewayInstantiation</code> verwendet wird, ist <code>unicastCredentials</code> zwingend für die statische Bereitstellung von IP/Port zu modellieren, falls kein dynamischer Service-Discovery-Mechanismus greift.\n</li></ul>\n</li><li><strong>Security &amp; Krypto-Stack-Integration:</strong>\n<ul class=\"fig-list\"><li>Verlinkung auf <code>TlsSecureComProps</code> bedingt die Bereitstellung entsprechender Crypto-Treiber und Schlüssel im <em>Crypto Service Manager</em> (CSM / Key Storage Providers).\n</li><li>Externe und interne Verbindungen können unterschiedliche Sicherheitsstufen besitzen (<code>securePropsForExternalComm</code> vs. <code>securePropsForTcp/Udp</code>).\n</li></ul>\n</li><li><strong>Netzwerk-Stack-Bindung:</strong>\n<ul class=\"fig-list\"><li><code>EthernetCommunicationConnector</code> erfordert zwingend konsistente MTU- (<code>maximumTransmissionUnit</code>) und Path-MTU-Konfigurationen (<code>pathMtuEnabled</code>, <code>pathMtuTimeout</code>), um IP-Fragmentierung bei großen diagnostischen JSON-/REST-Payloads zu verhindern.\n</li><li>Die Zuordnung zu <code>ApApplicationEndpoint</code> bestimmt die Port-Mappings auf POSIX-Socket-Ebene für den generierten Applikations-Code.\n</li></ul>\n</li></ul>"}, {"id": "FIG-99d741c18b97f047", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm (AUTOSAR M2/M3-Metamodell-Ausschnitt, <em>Manifest Specification</em>).\n</li><li><strong>Technischer Zweck:</strong> Modellierung der Bereitstellung und Kommunikationsanbindung von <strong>SOVD</strong> (<em>Service-Oriented Vehicle Diagnostics</em>, ASAM SOVD) in der AUTOSAR Adaptive Platform (Release R22-11).\n</li><li><strong>Architektonische Einordnung:</strong>\n<ul class=\"fig-list\"><li>Spezialisierung von <code>NonOsModuleInstantiation</code> zur softwareseitigen Instanziierung von SOVD-Funktionsbausteinen auf einer <em>Adaptive Machine</em>.\n</li><li>Differenzierung zwischen internen Diagnose-Servern (<code>SovdServerInstantiation</code>) und fahrzeugzentralen/externen Diagnose-Gateways (<code>SovdGatewayInstantiation</code>).\n</li><li>Abbildung der Netzwerk- und Transportschicht-Parametrierung (Ethernet, TCP/UDP-Endpoints, TLS-Absicherung) über AUTOSAR-Standardelemente (<code>CommunicationConnector</code>, <code>SecureComProps</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metamodell-Klassen &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>SovdModuleInstantiation</code></strong> <em>(abstract, spezialisiert <code>NonOsModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Basisklasse aller SOVD-Instanzen im Manifest.\n</li><li>Attribut: <code>nodeIdentifier: String [0..1]</code> – Eindeutiger logischer Bezeichner des SOVD-Knotens im Fahrzeugnetzwerk.\n</li></ul>\n</li><li><strong><code>SovdServerInstantiation</code></strong> <em>(konkret, spezialisiert <code>SovdModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Repräsentiert einen lokalen SOVD-Server, der Diagnoseressourcen einer bestimmten Fahrzeugkomponente bereitstellt.\n</li><li>Attribut: <code>componentQualifier: String [0..1]</code> – Bezeichner der diagnostizierten logischen/physischen Komponente gemäß SOVD-Spezifikation.\n</li></ul>\n</li><li><strong><code>SovdGatewayInstantiation</code></strong> <em>(konkret, spezialisiert <code>SovdModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Repräsentiert das SOVD-Gateway, das externe REST-/WebSocket-Anfragen bündelt, terminiert und an interne Server/Subsysteme vermittelt.\n</li></ul>\n</li><li><strong><code>SovdGatewayEthernetCredentials</code></strong> <em>(abstract)</em>:\n<ul class=\"fig-list\"><li>Basisstruktur für Netzwerkadressierungsdaten des Gateways.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>ipv4Address: Ip4AddressString [0..1]</code>\n</li><li><code>ipv6Address: Ip6AddressString [0..1]</code>\n</li><li><code>udpPort: PositiveInteger [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><strong><code>SovdGatewayLocalEndpointTcpConfig</code></strong> <em>(konkret, spezialisiert <code>SovdGatewayEthernetCredentials</code>)</em>:\n<ul class=\"fig-list\"><li>Konfiguriert die lokalen TCP-Endpunkte des SOVD-Gateways.\n</li><li>Attribut: <code>tcpPort: PositiveInteger [0..1]</code>\n</li></ul>\n</li><li><strong><code>SecureComProps</code></strong> <em>(abstract, Basisklassen: <code>ARElement</code>, <code>UploadableDesignElement</code>)</em> / <strong><code>TlsSecureComProps</code></strong> <em>(konkret)</em>:\n<ul class=\"fig-list\"><li>Sicherheitskonfiguration für verschlüsselte Kommunikationsverbindungen (TLS/DTLS). Qualifiziert als <code>UploadableDesignElement</code> für das Design- und Update-Management.\n</li></ul>\n</li><li><strong><code>CommunicationConnector</code></strong> <em>(abstract, Basisklasse: <code>Identifiable</code>)</em>:\n<ul class=\"fig-list\"><li>Physischer/logischer Netzanbindungspunkt.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>createEcuWakeupSource: Boolean [0..1]</code>\n</li><li><code>pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code>\n</li></ul>\n</li></ul>\n</li><li><strong><code>EthernetCommunicationConnector</code></strong> <em>(konkret, spezialisiert <code>CommunicationConnector</code>)</em>:\n<ul class=\"fig-list\"><li>Spezifische Ethernet-Netzwerkankopplung.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>maximumTransmissionUnit: PositiveInteger [0..1]</code>\n</li><li><code>neighborCacheSize: PositiveInteger [0..1]</code>\n</li><li><code>pathMtuEnabled: Boolean [0..1]</code>\n</li><li><code>pathMtuTimeout: TimeValue [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><strong><code>NetworkEndpoint</code></strong> <em>(konkret, Basisklasse: <code>Identifiable</code>)</em>:\n<ul class=\"fig-list\"><li>Spezifiziert IP-Ebene und Host-Konfiguration.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>fullyQualifiedDomainName: String [0..1]</code>\n</li><li><code>priority: PositiveInteger [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><strong><code>ApApplicationEndpoint</code></strong> <em>(konkret, Basisklasse: <code>Identifiable</code>)</em>:\n<ul class=\"fig-list\"><li>Spezifischer Anwendungs-Endpunkt auf Socket-Ebene.\n</li><li>Attribut: <code>priority: PositiveInteger [0..1]</code>\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen, Aggregationen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>SovdModuleInstantiation</code> → <code>CommunicationConnector</code>:</strong>\n<ul class=\"fig-list\"><li>Assoziation <code>+communicationConnector</code> (<code>0..*</code>): Weist der SOVD-Modulinstanz Netzwerk-Konnektoren der Machine zu.\n</li></ul>\n</li><li><strong><code>SovdModuleInstantiation</code> → <code>SecureComProps</code>:</strong>\n<ul class=\"fig-list\"><li>Assoziation <code>+securePropsForTcp</code> (<code>0..1</code>): Sicherheitskonfiguration für interne TCP-Verbindungen.\n</li><li>Assoziation <code>+securePropsForUdp</code> (<code>0..1</code>): Sicherheitskonfiguration für interne UDP-Verbindungen.\n</li></ul>\n</li><li><strong><code>SovdGatewayInstantiation</code> → <code>SecureComProps</code>:</strong>\n<ul class=\"fig-list\"><li>Assoziation <code>+securePropsForExternalComm</code> (<code>0..1</code>): TLS-Sicherheitskonfiguration (<code>TlsSecureComProps</code>) für externe SOVD-Kommunikationskanäle.\n</li></ul>\n</li><li><strong><code>SovdGatewayInstantiation</code> → <code>SovdGatewayLocalEndpointTcpConfig</code>:</strong>\n<ul class=\"fig-list\"><li>Komposition <code>+unicastCredentials</code> (<code>0..1</code>): Besitzt lokale TCP-Verbindungs- und Adressierungsdaten des Gateways.\n</li></ul>\n</li><li><strong><code>EthernetCommunicationConnector</code> → <code>NetworkEndpoint</code>:</strong>\n<ul class=\"fig-list\"><li>Assoziation <code>+unicastNetworkEndpoint</code> (<code>0..*</code>): Referenziert IP-Endpunkte des Netzwerkinterfaces.\n</li></ul>\n</li><li><strong><code>EthernetCommunicationConnector</code> → <code>ApApplicationEndpoint</code>:</strong>\n<ul class=\"fig-list\"><li>Komposition <code>+apApplicationEndpoint</code> (<code>0..*</code>): Aggregiert Socket-Endpunkte für Anwendungen.\n</li></ul>\n</li><li><strong>Generalisierungs-Hierarchien:</strong>\n<ul class=\"fig-list\"><li><code>SovdServerInstantiation</code> → <code>SovdModuleInstantiation</code> → <code>NonOsModuleInstantiation</code>\n</li><li><code>SovdGatewayInstantiation</code> → <code>SovdModuleInstantiation</code> → <code>NonOsModuleInstantiation</code>\n</li><li><code>SovdGatewayLocalEndpointTcpConfig</code> → <code>SovdGatewayEthernetCredentials</code>\n</li><li><code>EthernetCommunicationConnector</code> → <code>CommunicationConnector</code> → <code>Identifiable</code>\n</li><li><code>TlsSecureComProps</code> → <code>SecureComProps</code> → <code>ARElement</code>, <code>UploadableDesignElement</code>\n</li><li><code>NetworkEndpoint</code> → <code>Identifiable</code>\n</li><li><code>ApApplicationEndpoint</code> → <code>Identifiable</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein rein deklaratives Metamodell-Diagramm handelt, sind keine Laufzeit-Zustandsübergänge abgebildet. Für die Systemintegration bestimmt das Modell folgende Initialisierungs- und Kommunikationsabläufe:</p>\n<pre class=\"fig-pre\"><code>[Externer SOVD-Client]\n       |\n       | 1. TCP Connect (IP/Port via SovdGatewayLocalEndpointTcpConfig)\n       v\n[SovdGatewayInstantiation]\n       |\n       | 2. TLS Handshake (Validierung via securePropsForExternalComm / TlsSecureComProps)\n       v\n[Authentifizierter Session-Kanal]\n       |\n       | 3. Routing anhand URI / nodeIdentifier / componentQualifier\n       +--------------------------------------------+\n       |                                            |\n       v (interne TCP/UDP-Kommunikation)            v\n[SovdServerInstantiation A]               [SovdServerInstantiation B]\n(abgesichert via securePropsForTcp/Udp)  (abgesichert via securePropsForTcp/Udp)</code></pre>\n<ol class=\"fig-list\"><li><strong>Stack-Bootstrapping:</strong> Der Adaptive-Core wertet das Manifest aus, instanziiert den SOVD-Gateway-Daemon und bindet diesen an die via <code>+unicastCredentials</code> konfigurierte IP-Adresse und den <code>tcpPort</code>.\n</li><li><strong>TLS-Terminierung am Gateway:</strong> Eingehende Client-Verbindungen werden über die in <code>+securePropsForExternalComm</code> referenzierten Zertifikate/Cipher-Suites (<code>TlsSecureComProps</code>) authentifiziert und entschlüsselt.\n</li><li><strong>Dispatching:</strong> Das Gateway löst eingehende REST-/JSON-Anfragen über den Pfad auf:\n<ul class=\"fig-list\"><li>Zuordnung zur passenden <code>SovdServerInstantiation</code> via <code>nodeIdentifier</code> bzw. <code>componentQualifier</code>.\n</li><li>Weiterleitung über die internen Endpunkte (<code>EthernetCommunicationConnector</code>), optional getrennt abgesichert über <code>securePropsForTcp</code>/<code>securePropsForUdp</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Konfiguration (TPS_MANI_01400, TPS_MANI_01401):</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen bei der Manifest-Erstellung entscheiden, ob ein Prozess als vollwertiges Gateway (<code>SovdGatewayInstantiation</code>) oder als reiner interner Server (<code>SovdServerInstantiation</code>) fungiert.\n</li><li>Wenn <code>SovdGatewayInstantiation</code> verwendet wird, ist <code>unicastCredentials</code> zwingend für die statische Bereitstellung von IP/Port zu modellieren, falls kein dynamischer Service-Discovery-Mechanismus greift.\n</li></ul>\n</li><li><strong>Security &amp; Krypto-Stack-Integration:</strong>\n<ul class=\"fig-list\"><li>Verlinkung auf <code>TlsSecureComProps</code> bedingt die Bereitstellung entsprechender Crypto-Treiber und Schlüssel im <em>Crypto Service Manager</em> (CSM / Key Storage Providers).\n</li><li>Externe und interne Verbindungen können unterschiedliche Sicherheitsstufen besitzen (<code>securePropsForExternalComm</code> vs. <code>securePropsForTcp/Udp</code>).\n</li></ul>\n</li><li><strong>Netzwerk-Stack-Bindung:</strong>\n<ul class=\"fig-list\"><li><code>EthernetCommunicationConnector</code> erfordert zwingend konsistente MTU- (<code>maximumTransmissionUnit</code>) und Path-MTU-Konfigurationen (<code>pathMtuEnabled</code>, <code>pathMtuTimeout</code>), um IP-Fragmentierung bei großen diagnostischen JSON-/REST-Payloads zu verhindern.\n</li><li>Die Zuordnung zu <code>ApApplicationEndpoint</code> bestimmt die Port-Mappings auf POSIX-Socket-Ebene für den generierten Applikations-Code.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-eeae4c0dfe722a81", "to": "FIG-555910f9c3304252", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>SecureComProps</code>: Metaklasse erbt nun zusätzlich von <code>UploadableDesignElement</code> (neben <code>ARElement</code>).\n</li></ul>"}, {"from": "FIG-555910f9c3304252", "to": "FIG-95dd614989bc744b", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-95dd614989bc744b", "to": "FIG-99d741c18b97f047", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
